import { test, expect } from '@playwright/test';

test.describe('Modal Title Announcement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-page');
  });

  test('should announce modal title when opened', async ({ page }) => {
    // Open the modal by clicking the button
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Wait for the modal to appear
    const modal = page.locator('[data-testid="modal-container"]');
    await expect(modal).toBeVisible();

    // Verify the modal title is visible
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Verify the modal content is visible
    const modalContent = page.locator('[data-testid="modal-content"]');
    await expect(modalContent).toBeVisible();

    // Verify the modal has aria-modal attribute
    const hasAriaModal = await modal.getAttribute('aria-modal');
    expect(hasAriaModal).toBe('true');

    // Verify the modal has role="dialog"
    const hasDialogRole = await modal.getAttribute('role');
    expect(hasDialogRole).toBe('dialog');
  });

  test('should close modal and remove title announcement when closed', async ({ page }) => {
    // Open the modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Wait for the modal to appear
    const modal = page.locator('[data-testid="modal-container"]');
    await expect(modal).toBeVisible();

    // Verify modal title is visible
    const modalTitle = page.getByRole('heading', { name: /modal title/i });
    await expect(modalTitle).toBeVisible();

    // Close the modal by clicking the close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Wait for the modal to close
    await expect(modal).not.toBeVisible();

    // Verify modal title is no longer visible
    await expect(modalTitle).not.toBeVisible();

    // Verify modal has no aria-modal attribute
    const hasAriaModal = await modal.getAttribute('aria-modal');
    expect(hasAriaModal).toBeNull();
  });
});
